const items = $input.all();
const result = [];
for (const item of items) {
  const data = item.json;
  const jobs = Array.isArray(data) ? data : [data];
  for (const job of jobs) {
    if (!job || typeof job !== 'object') continue;
    if (!job.id || job.legal !== undefined || !job.url) continue;
    result.push({
      json: {
        job_title: (job.position || '').trim(),
        company: (job.company || '').trim(),
        job_url: job.url || ('https://remoteok.com/remote-jobs/' + job.id),
        source: 'RemoteOK',
        location_text: job.location || 'worldwide',
        salary: job.salary_min ? ('$' + job.salary_min + ' - $' + job.salary_max + '/yr') : '',
        description: (job.description || '').replace(/<[^>]*>/g, '').slice(0, 3000),
        posted_date: job.date ? new Date(parseInt(job.date) * 1000).toISOString().split('T')[0] : '',
        tags: Array.isArray(job.tags) ? job.tags.join(', ') : (job.tags || ''),
        job_id: 'remoteok_' + job.id
      }
    });
  }
}
return result;

const items = $input.all();
const result = [];
for (const item of items) {
  const data = item.json;
  const jobs = data.jobs || (Array.isArray(data) ? data : []);
  for (const job of jobs) {
    if (!job || !job.url) continue;
    result.push({
      json: {
        job_title: (job.title || '').trim(),
        company: (job.company_name || '').trim(),
