const items = $input.all();
return items.map(item => {
  const rss = item.json;
  const url = rss.link || '';
  const titleRaw = rss.title || '';
  const companyMatch = titleRaw.match(/^(.+?):/);
  const company = companyMatch ? companyMatch[1].trim() : '';
  const jobTitle = titleRaw.replace(/^.+?:\s*/, '').trim();
  const idMatch = url.match(/\/jobs\/(\d+)/);
  return {
    json: {
      job_title: jobTitle,
      company: company,
      job_url: url,
      source: 'WeWorkRemotely',
      location_text: 'worldwide',
      salary: '',
      description: (rss.content || rss.description || '').replace(/<[^>]*>/g, '').slice(0, 3000),
      posted_date: rss.pubDate ? new Date(rss.pubDate).toISOString().split('T')[0] : '',
      tags: '',
      job_id: 'wwr_' + (idMatch ? idMatch[1] : Math.random().toString(36).slice(2))
    }
  };
}).filter(i => i.json.job_url && i.json.job_title);

// Wellfound does not have a public API.
// This node parses basic job data from the HTML response.
// For production use, configure a Wellfound API token or use Apify.
const items = $input.all();
const result = [];
for (const item of items) {
  const html = typeof item.json === 'string' ? item.json : JSON.stringify(item.json);
  const jobMatches = html.matchAll(/href="(\/jobs\/[^"]+)"[^>]*>[^<]*<[^>]*>([^<]{5,100})<\/[^>]*>[^<]*<[^>]*>([^<]{2,80})/g);
  for (const match of jobMatches) {
    const path = match[1];
    const title = match[2].trim();
    const company = match[3].trim();
    if (!path || !title || title.length < 5) continue;
    result.push({
      json: {
        job_title: title,
        company: company,
        job_url: 'https://wellfound.com' + path,
        source: 'Wellfound',
        location_text: 'worldwide',
        salary: '',
        description: title + ' at ' + company + ' (remote)',
        posted_date: new Date().toISOString().split('T')[0],
        tags: 'startup, remote',
        job_id: 'wellfound_' + path.replace(/[^a-z0-9]/gi, '_')
      }
    });
  }
}
return result.slice(0, 50);

const items = $input.all();
const result = [];
for (const item of items) {
  const data = item.json;
  const jobs = data.jobs || (Array.isArray(data) ? data : []);
  for (const job of jobs) {
    if (!job) continue;
    const url = job.applicationLink || (job.slug ? 'https://himalayas.app/jobs/companies/' + (job.company?.slug || '') + '/' + job.slug : '');
    if (!url) continue;
    const locRestrictions = Array.isArray(job.locationRestrictions) ? job.locationRestrictions : [];
    const locText = locRestrictions.length === 0 ? 'worldwide' : locRestrictions.join(', ');
    result.push({
      json: {
        job_title: (job.title || '').trim(),
        company: (job.company?.name || job.companyName || '').trim(),
        job_url: url,
        source: 'Himalayas',
        location_text: locText,
        salary: (job.minAnnualSalary && job.maxAnnualSalary) ? ('$' + job.minAnnualSalary + ' - $' + job.maxAnnualSalary + '/yr') : '',
        description: (job.description || '').replace(/<[^>]*>/g, '').slice(0, 3000),
        posted_date: job.publishedAt ? job.publishedAt.split('T')[0] : '',
        tags: Array.isArray(job.categories) ? job.categories.join(', ') : '',
        job_id: 'himalayas_' + (job.id || job.slug || Math.random().toString(36).slice(2))
      }
    });
  }
}
return result;

const items = $input.all();
return items.map(item => {
  const rss = item.json;
  const url = rss.link || rss.guid || '';
  return {
    json: {
      job_title: (rss.title || '').replace(/<[^>]*>/g, '').trim(),
      company: (rss.author || rss['dc:creator'] || '').replace(/<[^>]*>/g, '').trim(),
      job_url: url,
      source: 'DynamiteJobs',
      location_text: 'worldwide',
      salary: '',
      description: (rss.content || rss.description || rss.summary || '').replace(/<[^>]*>/g, '').slice(0, 3000),
      posted_date: rss.pubDate ? new Date(rss.pubDate).toISOString().split('T')[0] : '',
      tags: 'remote, nomad',
      job_id: 'dynamite_' + (url.split('/').pop() || Math.random().toString(36).slice(2))
    }
  };
}).filter(i => i.json.job_url && i.json.job_title);

// YC Work at a Startup - parse from HTML or JSON response
const items = $input.all();
const result = [];
for (const item of items) {
  const raw = item.json;
  // Handle JSON array response
  const jobs = Array.isArray(raw) ? raw : (raw.jobs || raw.data || []);
  for (const job of jobs) {
    if (typeof job !== 'object' || !job) continue;
    const url = job.url || (job.id ? 'https://www.workatastartup.com/jobs/' + job.id : '');
    if (!url) continue;
    result.push({
      json: {
        job_title: (job.title || job.role || '').trim(),
        company: (job.company?.name || job.companyName || '').trim(),
        job_url: url,
        source: 'YC WaaS',
        location_text: job.remote ? 'worldwide' : (job.location || 'unknown'),
        salary: job.minSalary ? ('$' + job.minSalary + ' - $' + (job.maxSalary || job.minSalary) + '/yr') : '',
        description: (job.description || job.body || '').replace(/<[^>]*>/g, '').slice(0, 3000),
        posted_date: job.createdAt ? job.createdAt.split('T')[0] : new Date().toISOString().split('T')[0],
        tags: Array.isArray(job.tags) ? job.tags.join(', ') : (job.jobType || ''),
        job_id: 'yc_' + (job.id || Math.random().toString(36).slice(2))
      }
    });
  }
}
return result;

// Otta - parse API response (may require authentication in production)
const items = $input.all();
const result = [];
for (const item of items) {
  const raw = item.json;
  const jobs = Array.isArray(raw) ? raw : (raw.data || raw.jobs || raw.results || []);
  for (const job of jobs) {
    if (typeof job !== 'object' || !job) continue;
    const url = job.url || (job.id ? 'https://app.otta.com/jobs/' + job.id : '');
    if (!url) continue;
    result.push({
      json: {
        job_title: (job.title || job.function || '').trim(),
        company: (job.company?.name || job.companyName || '').trim(),
        job_url: url,
        source: 'Otta',
        location_text: job.remote ? 'worldwide' : (job.locationCity || 'unknown'),
        salary: (job.salaryMin && job.salaryMax) ? ('$' + job.salaryMin + ' - $' + job.salaryMax) : '',
        description: (job.description || job.bullets?.map(b => b.text)?.join(' ') || '').replace(/<[^>]*>/g, '').slice(0, 3000),
        posted_date: job.liveAt ? job.liveAt.split('T')[0] : new Date().toISOString().split('T')[0],
        tags: Array.isArray(job.technologies) ? job.technologies.join(', ') : '',
        job_id: 'otta_' + (job.externalId || job.id || Math.random().toString(36).slice(2))
      }
    });
  }
}
return result;

const items = $input.all();
const today = new Date().toISOString().split('T')[0];

// Keyword filter — only keep jobs relevant to our search terms
const KEEP_KEYWORDS = [
  'async', 'asynchronous', 'worldwide', 'global remote', 'work from anywhere',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'performance marketing',
  'ai marketing', 'ai automation', 'ai workflow', 'machine learning',
  'marketing', 'analytics', 'automation', 'tableau', 'power bi',
  'python', 'sql', 'martech', 'creative strategist', 'seo', 'ppc',
  'google ads', 'meta ads', 'digital marketing', 'remote'
];

const cleaned = [];
for (const item of items) {
  const job = item.json;
  if (!job.job_title || !job.job_url) continue;

  const searchText = (job.job_title + ' ' + (job.description || '') + ' ' + (job.tags || '')).toLowerCase();
  const hasKeyword = KEEP_KEYWORDS.some(kw => searchText.includes(kw.toLowerCase()));
  if (!hasKeyword) continue;

  cleaned.push({
    json: {
      date_found: today,
      job_title: (job.job_title || '').trim().slice(0, 200),
      company: (job.company || '').trim().slice(0, 100),
      job_url: (job.job_url || '').trim().split('?')[0],
      source: job.source || 'Unknown',
      location_text: (job.location_text || 'worldwide').trim().slice(0, 200),
      salary: (job.salary || '').trim().slice(0, 100),
      description: (job.description || '').trim().slice(0, 3000),
      posted_date: job.posted_date || today,
      tags: (job.tags || '').toLowerCase().slice(0, 500),
      job_id: job.job_id || (job.source + '_' + job.job_url.slice(-20).replace(/[^a-z0-9]/gi, ''))
    }
  });
}

return cleaned;

// Use workflow static data to track seen job URLs across executions
const staticData = $getWorkflowStaticData('global');
const seenUrls = new Set(staticData.seenUrls || []);
const seenKeys = new Set(staticData.seenKeys || []);

// Prune old entries (keep last 3000 to avoid bloat)
if (seenUrls.size > 3000) {
  const arr = Array.from(seenUrls);
  staticData.seenUrls = arr.slice(arr.length - 2500);
  seenUrls.clear();
  staticData.seenUrls.forEach(u => seenUrls.add(u));
}

const items = $input.all();
const newJobs = [];

for (const item of items) {
  const job = item.json;
  const urlKey = (job.job_url || '').toLowerCase().replace(/\/+$/, '').trim();
  const companyTitleKey = ((job.company || '') + '|' + (job.job_title || '')).toLowerCase().trim();

  if (!urlKey) continue;
  if (seenUrls.has(urlKey)) continue;
  if (seenKeys.has(companyTitleKey) && companyTitleKey.length > 3) continue;

  seenUrls.add(urlKey);
  seenKeys.add(companyTitleKey);
  newJobs.push({ json: job });
}

// Persist updated sets
staticData.seenUrls = Array.from(seenUrls);
staticData.seenKeys = Array.from(seenKeys).slice(-3000);

return newJobs;

// Hard filter — reject obvious country-restricted or non-remote jobs
const REJECT_PHRASES = [
  'us only', 'usa only', 'united states only', 'u.s. only', 'must be us based',
  'canada only', 'canadian only', 'must be based in canada',
  'uk only', 'united kingdom only', 'must be uk based',
  'eu only', 'europe only', 'european union only', 'must be based in the eu',
  'australia only', 'must be based in australia',
  'new zealand only', 'germany only', 'france only', 'netherlands only',
  'must be based in', 'must live in', 'must reside in',
  'must be authorized to work in', 'must be legally authorized',
  'work authorization required', 'local work permit',
  'visa sponsorship not available for this role and we are not able',
  'legally authorized to work in the us',
  'authorized to work in the united states',
  'right to work in the uk',
  'must be in us timezone', 'us timezone required',
  'hybrid', 'on-site', 'onsite', 'in-office', 'office required',
  'in person', 'must be local', 'remote within us', 'remote within the us',
  'remote within united states', 'remote in the us only',
  'remote within europe', 'remote within uk', 'remote within canada',
  'fixed us hours', 'fixed eu hours', 'fixed eastern time only',
  'fixed pst only', 'must work eastern time', 'must work pacific time',
  'must overlap us business hours', 'must be available 9-5 est'
];

const OVERRIDE_PHRASES = [
  'worldwide', 'work from anywhere', 'global remote', 'anywhere in the world',
  'internationally', 'all countries', 'international contractors',
  'apac', 'asia pacific', 'distributed team', 'remote first',
  'contractor', 'freelance', 'deel', 'remote.com', 'oyster',
  'employer of record', 'eor', 'b2b contractor', 'open to all locations'
];

const passed = [];
const rejected = [];
const today = new Date().toISOString().split('T')[0];

for (const item of $input.all()) {
  const job = item.json;
  const searchText = [
    job.job_title || '',
    job.location_text || '',
    job.description || '',
    job.tags || ''
  ].join(' ').toLowerCase();

  let rejectReason = null;
  for (const phrase of REJECT_PHRASES) {
    if (searchText.includes(phrase)) {
      const hasOverride = OVERRIDE_PHRASES.some(op => searchText.includes(op));
      if (!hasOverride) {
        rejectReason = phrase;
        break;
      }
    }
  }

  if (rejectReason) {
    rejected.push({
      json: {
        date_rejected: today,
        job_title: job.job_title,
        company: job.company,
        job_url: job.job_url,
        reason: 'Hard filter: "' + rejectReason + '"'
      }
    });
  } else {
    passed.push({ json: job });
  }
}

return [passed, rejected];

const items = $input.all();
const result = [];

for (const item of items) {
  const job = item.json;
  // The OpenAI node returns the message content in message.content
  let aiText = '';
  try {
    aiText = job.message?.content || job.choices?.[0]?.message?.content || JSON.stringify(job);
  } catch (e) {
    aiText = '{}';
  }

  let aiData = {};
  try {
    // Extract JSON from response (handle markdown code blocks if present)
    const jsonMatch = aiText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      aiData = JSON.parse(jsonMatch[0]);
    }
  } catch (e) {
    aiData = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check',
      why_good_fit: 'Could not parse AI response'
    };
  }

  // Merge AI fields back into the original job data
  // The input to the AI node was the job, so we need to reconstruct
  // n8n's OpenAI node wraps the original item — extract it
  const originalJob = job.input || {};

  result.push({
    json: {
      // Keep all original job fields
      date_found: originalJob.date_found || job.date_found || '',
      job_title: originalJob.job_title || job.job_title || '',
      company: originalJob.company || job.company || '',
      job_url: originalJob.job_url || job.job_url || '',
      source: originalJob.source || job.source || '',
      location_text: originalJob.location_text || job.location_text || '',
      salary: originalJob.salary || job.salary || '',
      description: originalJob.description || job.description || '',
      posted_date: originalJob.posted_date || job.posted_date || '',
      tags: originalJob.tags || job.tags || '',
      job_id: originalJob.job_id || job.job_id || '',
      // AI-generated fields
      taiwan_eligible: aiData.taiwan_eligible || 'unclear',
      taiwan_reason: aiData.reason || '',
      location_risk: aiData.location_risk || 'medium',
      timezone_risk: aiData.timezone_risk || 'medium',
      contractor_possible: aiData.contractor_possible || 'unclear',
      ai_decision: aiData.decision || 'manual_check',
      why_good_fit: aiData.why_good_fit || ''
    }
  });
}

return result;

const ASYNC_HIGH = [
  'async', 'asynchronous', 'async-first', 'async communication',
  'no meetings', 'low meeting', 'no standup', 'fully async', 'async by default'
];
const ASYNC_MEDIUM = [
  'flexible hours', 'flexible schedule', 'flexible working hours',
  'results-driven', 'results oriented', 'outcomes over hours',
  'work across time zones', 'global team', 'distributed team',
  'remote first', 'remote-first', 'you choose your hours'
];
const ASYNC_LOW = [
  'work from home', 'remote', 'wfh', 'distributed', 'virtual team'
];
const SYNC_REJECT = [
  'strict 9 to 5', 'strict 9-5', 'fixed us hours',
  'fixed est', 'fixed pst', 'fixed cet', 'daily live calls required',
  'must overlap full business day', 'must be online during business hours',
  'real-time availability required', 'sync-heavy'
];

const items = $input.all();
return items.map(item => {
  const job = item.json;
  const text = (job.description + ' ' + job.tags + ' ' + job.job_title).toLowerCase();

  // Check for hard sync rejectors
  const isSyncHeavy = SYNC_REJECT.some(s => text.includes(s));
  if (isSyncHeavy) {
    return { json: { ...job, async_level: 'sync_heavy', async_flag: false } };
  }

  let asyncLevel = 'unknown';
  if (ASYNC_HIGH.some(a => text.includes(a))) {
    asyncLevel = 'high';
  } else if (ASYNC_MEDIUM.some(a => text.includes(a))) {
    asyncLevel = 'medium';
  } else if (ASYNC_LOW.some(a => text.includes(a))) {
    asyncLevel = 'low';
  }

  return { json: { ...job, async_level: asyncLevel, async_flag: asyncLevel !== 'sync_heavy' } };
}).filter(item => item.json.async_level !== 'sync_heavy');

const ROLE_CATEGORIES = {
  'data_analyst': [
    'data analyst', 'analytics analyst', 'data analysis', 'business analyst',
    'reporting analyst', 'insights analyst'
  ],
  'data_scientist': [
    'data scientist', 'junior data scientist', 'machine learning engineer',
    'ml engineer', 'data science', 'applied scientist'
  ],
  'bi_analyst': [
    'business intelligence', 'bi analyst', 'bi developer', 'bi engineer',
    'tableau developer', 'power bi developer', 'dashboard analyst'
  ],
  'marketing_analyst': [
    'marketing analyst', 'digital marketing analyst', 'performance marketing analyst',
    'paid media analyst', 'ppc analyst', 'seo analyst', 'search analyst',
    'conversion analyst', 'acquisition analyst', 'growth analyst'
  ],
  'ai_specialist': [
    'ai marketing', 'ai specialist', 'ai automation', 'ai workflow',
    'prompt engineer', 'llm', 'generative ai', 'ai tools specialist',
    'chatgpt', 'automation specialist', 'no-code automation'
  ],
  'martech_analyst': [
    'martech', 'marketing technology', 'marketing operations', 'marketing ops',
    'crm analyst', 'ga4', 'google analytics', 'attribution analyst'
  ],
  'creative_data': [
    'creative strategist', 'creative analyst', 'content strategist with data',
    'growth marketer', 'growth hacker', 'performance creative'
  ]
};

const ADJACENT_ROLES = [
  'product analyst', 'product manager', 'operations analyst',
  'revenue operations', 'sales analyst', 'financial analyst',
  'market research analyst', 'e-commerce analyst', 'social media analyst'
];

const items = $input.all();
return items.map(item => {
  const job = item.json;
  const text = (job.job_title + ' ' + job.description + ' ' + job.tags).toLowerCase();

  let roleCategory = 'other';
  let roleFitScore = 0;

  for (const [category, keywords] of Object.entries(ROLE_CATEGORIES)) {
    if (keywords.some(kw => text.includes(kw))) {
      roleCategory = category;
      roleFitScore = 25;
      break;
    }
  }

  if (roleFitScore === 0 && ADJACENT_ROLES.some(r => text.includes(r))) {
    roleCategory = 'adjacent';
    roleFitScore = 15;
  }

  return { json: { ...job, role_category: roleCategory, role_fit_score: roleFitScore } };
});

const items = $input.all();

return items.map(item => {
  const job = item.json;
  let score = 0;
  const scoreBreakdown = [];

  // ── Taiwan Eligibility: max 40 pts ──
  const text = (job.description + ' ' + job.location_text + ' ' + job.tags).toLowerCase();
  const clearlyGlobal = [
    'worldwide', 'work from anywhere', 'global remote', 'anywhere',
    'internationally', 'open to all', 'all countries', 'contractor'
  ].some(kw => text.includes(kw));
  const apacFriendly = ['apac', 'asia', 'asia pacific', 'east asia', 'southeast asia'].some(kw => text.includes(kw));

  if (job.taiwan_eligible === 'yes' || clearlyGlobal) {
    score += 40;
    scoreBreakdown.push('Taiwan eligible (worldwide/contractor): +40');
  } else if (job.taiwan_eligible === 'yes' && apacFriendly) {
    score += 30;
    scoreBreakdown.push('APAC friendly: +30');
  } else if (job.taiwan_eligible === 'unclear' && job.location_risk !== 'high') {
    score += 20;
    scoreBreakdown.push('Unclear but no hard restriction: +20');
  } else {
    scoreBreakdown.push('Country restricted: +0');
  }

  // ── Async Fit: max 25 pts ──
  if (job.async_level === 'high') {
    score += 25;
    scoreBreakdown.push('Clearly async: +25');
  } else if (job.async_level === 'medium') {
    score += 20;
    scoreBreakdown.push('Flexible hours: +20');
  } else if (job.async_level === 'low') {
    score += 10;
    scoreBreakdown.push('Remote first: +10');
  } else {
    score += 5;
    scoreBreakdown.push('Unknown async: +5');
  }

  // ── Role Fit: max 25 pts ──
  score += job.role_fit_score || 0;
  if (job.role_fit_score > 0) {
    scoreBreakdown.push('Role fit (' + job.role_category + '): +' + job.role_fit_score);
  }

  // ── Salary Fit: max 25 pts ──
  const salaryText = (job.salary || '').replace(/[^0-9,k]/gi, '');
  const salaryNumbers = salaryText.match(/\d[\d,]*/g) || [];
  const salaryValues = salaryNumbers.map(n => parseInt(n.replace(/,/g, '')) * (salaryText.toLowerCase().includes('k') ? 1000 : 1));
  const maxSalary = salaryValues.length > 0 ? Math.max(...salaryValues) : 0;
  const minSalary = salaryValues.length > 0 ? Math.min(...salaryValues) : 0;
  const annualSalary = maxSalary > 1000 ? maxSalary : maxSalary * 12;
  const monthlySalary = annualSalary > 0 ? annualSalary / 12 : minSalary;

  if (job.salary && monthlySalary >= 5000) {
    score += 25;
    scoreBreakdown.push('Salary $5k+/mo: +25');
  } else if (job.salary && monthlySalary >= 3000) {
    score += 15;
    scoreBreakdown.push('Salary $3k+/mo: +15');
  } else if (job.salary) {
    score += 10;
    scoreBreakdown.push('Salary listed: +10');
  }

  // ── Timezone Risk Bonus/Penalty ──
  if (job.timezone_risk === 'low') {
    score += 5;
    scoreBreakdown.push('Low timezone risk: +5');
  } else if (job.timezone_risk === 'high') {
    score -= 10;
    scoreBreakdown.push('High timezone risk: -10');
  }

  score = Math.max(0, Math.min(100, score));

  return {
    json: {
      ...job,
      score: score,
      score_breakdown: scoreBreakdown.join(' | ')
    }
  };
});

const items = $input.all();
