    score >= 70
  );

  if (!passesOneRule) {
    stats.low_score++;
    if (timezoneRisk === 'high') stats.timezone_risk++;
    rejected.push({
      json: {
        date_rejected: today,
        job_title: job.job_title,
        company: job.company,
        job_url: job.job_url,
        reason: aiDecision === 'reject' ? ('AI reject: ' + job.taiwan_reason) : ('Score ' + score + '/100')
      }
    });
    continue;
  }

