    json: {
      date_found: today,
      score: score,
      job_title: job.job_title,
      company: job.company,
      job_url: job.job_url,
      salary: job.salary,
      taiwan_eligible: job.taiwan_eligible,
      taiwan_reason: job.taiwan_reason,
      location_risk: job.location_risk,
